#!/bin/sh
# layer-2 load audit -- typescript -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_typescript.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_typescript
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_typescript.txt
: > "$OUT"
echo "=== layer-2 load audit -- typescript ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! test -x /persist/ts/node_modules/.bin/tsc >/dev/null 2>&1; then
  echo "typescript: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.null.null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > main.ts <<'L2_SRC_EOF'

function run(): void {
  let v: null = null;
  console.log("nothing.null.null" + "|" + (String(v)));
}
run();
L2_SRC_EOF
V=ok
if ! timeout 180 /persist/ts/node_modules/.bin/tsc --target es2020 --module commonjs main.ts > build.out 2> build.err; then V="<compile-error>"; fi
if [ "$V" = ok ]; then
  if timeout 30 node main.js > run.out 2> run.err; then :; else
    V="<aborted>"
  fi
  grep -F "nothing.null.null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.null.null|" "$OUT" || echo "nothing.null.null|$V" >> "$OUT"

